115	  }
116	  if (ar <= RV_MED) y = Math.max(y, ROAD + 0.3);                    // Bạch Đằng / Trần Hưng Đạo
117	  else if (ar <= RV_HALF) y = Math.max(y, ROAD + 0.02);
