196	/* Bán kính thân theo phần độ dài cung u (body.ts:15-20) */
197	function stSpineRadius(u: number): number {
198	  const Rb = CONFIG.bodyRadius, sm = (t: number) => t * t * (3 - 2 * t);
199	  if (u < 0.06) return 0.25 + (Rb - 0.25) * sm(u / 0.06);
200	  if (u > 0.95) return Rb + (CONFIG.headRadius - Rb) * sm((u - 0.95) / 0.05);
201	  return Rb;
202	}
