204	/* Thân / chân vòm / đầu / đuôi rồng trong tầm người: lấy mẫu đường tim, đánh dấu ô x (0,25 m) nơi ống thân (mặt cắt dọc z = 0)
205	   chạm dải [mặt cầu, mặt cầu + dải phân cách + REACH]; gộp ô liền nhau thành hình chữ nhật trên dải phân cách. */
206	function stDragonSolids(): StSolid[] {
207	  const pts = stSpinePoints(), N = 8000, p = { x: 0, y: 0 };
208	  const xs = new Float64Array(N + 1), ys = new Float64Array(N + 1), len = new Float64Array(N + 1);
209	  for (let i = 0; i <= N; i++) {
210	    stSpinePoint(pts, i / N, p); xs[i] = p.x; ys[i] = p.y;
211	    if (i > 0) len[i] = len[i - 1] + Math.hypot(xs[i] - xs[i - 1], ys[i] - ys[i - 1]);
212	  }
213	  const X0 = -400, STEP = 0.25, M = Math.round(800 / STEP) + 1;
214	  const half = new Float64Array(M);                                 // 0 = ô trống, > 0 = nửa bề ngang thân tại ô
215	  for (let i = 0; i <= N; i++) {
216	    const r = stSpineRadius(len[i] / len[N]), rr = 1.03 * r + 0.085;
217	    const g0 = Math.max(0, Math.ceil((xs[i] - rr - X0) / STEP)), g1 = Math.min(M - 1, Math.floor((xs[i] + rr - X0) / STEP));
218	    for (let g = g0; g <= g1; g++) {
219	      const x = X0 + g * STEP, lo = deckY(x), hi = lo + DR_MEDIAN + REACH;
220	      const yb = ys[i] < lo ? lo : ys[i] > hi ? hi : ys[i];
221	      const dx = xs[i] - x, dy = ys[i] - yb;
222	      if (dx * dx + dy * dy < rr * rr && rr > half[g]) half[g] = rr;
223	    }
