225	  const out: StSolid[] = [];
226	  let cur: StSolid = null, last = -Infinity;
227	  for (let g = 0; g < M; g++) {
228	    if (half[g] === 0) continue;
229	    const x = X0 + g * STEP;
230	    if (cur && x - last <= DR_ARCH_GAP) { cur.x1 = x + STEP; cur.z1 = Math.max(cur.z1, half[g]); cur.z0 = -cur.z1; }
231	    else { cur = { kind: 'rect', x0: x - STEP, x1: x + STEP, z0: -half[g], z1: half[g] }; out.push(cur); }
