237	/* Tháp chữ A, cột đôi, neo dây văng, hộp barie Cầu sông Hàn (tọa độ cục bộ + z cầu) */
238	function stSongHanSolids(): StSolid[] {
239	  const out: StSolid[] = [];
240	  const rect = (x0: number, x1: number, dz0: number, dz1: number, top?: number) => {
241	    const s: StSolid = { kind: 'rect', x0, x1, z0: SHZ + dz0, z1: SHZ + dz1 }; if (top !== undefined) s.top = top; out.push(s);
242	  };
243	  const H = SH_MEDIAN + REACH;                                      // tầm chặn tính từ mặt cầu, m
244	  rect(-0.4, 0.4, -1.0, 1.0);                                       // cột đôi ở tim (swingSpan.ts:45)
245	  const legIn = SH.aFoot - SH.aFoot * (H - 0.2) / (SH.aApex - 0.2); // ≈ 12,9 m — chân chữ A lên tới tầm H
246	  for (const s of [-1, 1]) {
247	    const a = legIn - 0.9, b = SH.aFoot + 0.9;                      // + nửa tiết diện 1,4 m chiếu ngang, làm tròn lên 0,9 (ước lượng)
248	    rect(s < 0 ? -b : a, s < 0 ? -a : b, -0.5, 0.5);                // chân chữ A, rộng 1,0 theo z
249	    for (let i = 0; i < SH.stays; i++) {                            // neo dây văng: dây thấp hơn tầm H trong đoạn gần neo
250	      const k = i / (SH.stays - 1), xd = SH.stayDeck[1] + (SH.stayDeck[0] - SH.stayDeck[1]) * k, top = SH.stayTop[1] + (SH.stayTop[0] - SH.stayTop[1]) * k;
251	      const xin = xd - (H - 0.35) * (xd - 0.5) / (top - 0.35);
252	      const a2 = xin - 0.1, b2 = xd + 0.3;                          // + bán kính dây, đầu neo (ước lượng)
253	      rect(s < 0 ? -b2 : a2, s < 0 ? -a2 : b2, -0.15, 0.15);        // dây 0,07 m + neo (ước lượng)
254	    }
255	    for (const sz of [-1, 1]) {                                     // hộp barie 0,45 × 1,0 trên gờ chắn bánh
256	      const bz = sz * (SH.hw - SH.sidewalk + 0.15);
257	      rect(s * SH.barrierX - 0.225, s * SH.barrierX + 0.225, bz - 0.225, bz + 0.225);
258	    }
259	    rect(-SH_X, SH_X, s < 0 ? -SH_CURB.z1 : SH_CURB.z0, s < 0 ? -SH_CURB.z0 : SH_CURB.z1, SH_CURB.top);   // gờ chắn bánh, liền qua khe nhịp quay
260	    for (const [x0, x1] of [[-SH_X, -SH.fixedStart], [SH.fixedStart, SH_X]]) {
261	      rect(x0, x1, s < 0 ? -SH_EDGE : SH_RAIL_IN, s < 0 ? -SH_RAIL_IN : SH_EDGE);   // lan can phần cố định (chặn hai đầu ở |x| = 290)
262	    }
263	  }
264	  return out;
265	}
