267	export function stBuildStructures(): StSolid[] {
268	  const out: StSolid[] = stDragonSolids();
269	  for (const s of [-1, 1]) {
270	    out.push({ kind: 'rect', x0: -DR_X, x1: DR_X, z0: s < 0 ? -DR_EDGE : DR_RAIL_IN, z1: s < 0 ? -DR_RAIL_IN : DR_EDGE });                 // lan can Cầu Rồng
271	    out.push({ kind: 'rect', x0: -DR_X, x1: DR_X, z0: s < 0 ? -DR_CURB.z1 : DR_CURB.z0, z1: s < 0 ? -DR_CURB.z0 : DR_CURB.z1, top: DR_CURB.top });   // gờ chắn xe
272	    out.push({ kind: 'rect', x0: LV_X0, x1: BK, z0: s < 0 ? LV.z - LV_RAIL : LV.z + LV_IN, z1: s < 0 ? LV.z - LV_IN : LV.z + LV_RAIL });      // lan can + khóa Cầu Tình Yêu
