274	  out.push(...stSongHanSolids());
275	  out.push({ kind: 'rect', x0: LV_X0 + 1.8 - 1.7, x1: LV_X0 + 1.8 + 1.7, z0: LV.z - 1.7, z1: LV.z + 1.7 });   // bệ + tượng cá chép hóa rồng (bệ cao 1,2 > lowMax)
