297	export interface StRect { x0: number; x1: number; z0: number; z1: number }
298	export interface StZone extends StRect { id: string; y: (x: number, z: number) => number; gate?: string }   // y: cao độ đứng tại (x, z), m
299	export interface StSolid { kind: 'rect' | 'circle'; x0?: number; x1?: number; z0?: number; z1?: number; cx?: number; cz?: number; r?: number; top?: number }   // top: m trên cao độ đứng; vắng = cao vô hạn
300	export interface StMap { zones: StZone[]; solids: StSolid[]; radius: number; closed: Set<string> }
301	
302	/* Chỉ mục lưới, giữ trong map nhưng không lộ ra kiểu công khai */
303	interface StIndex { cells: Map<number, number[]>; big: number[] }
304	interface StMapI extends StMap { idx: StIndex }
305	
306	const STC = 16;          // cạnh ô lưới, m (nhà ven sông 10–40 m, mỗi nhà phủ vài ô)
307	const ST_BIG = 64;       // vật cản phủ hơn số ô này thì vào danh sách "lớn"
308	const ST_OFF = 32768;    // dời chỉ số ô về số dương để ghép khóa (đủ cho ±524 km)
309	const stKey = (ix: number, iz: number): number => (ix + ST_OFF) * 65536 + (iz + ST_OFF);
310	
311	/* Thêm một vật cản (chỉ số i trong map.solids) vào lưới theo hộp bao của nó */
312	function stIndexOne(idx: StIndex, s: StSolid, i: number): void {
313	  const x0 = s.kind === 'circle' ? s.cx - s.r : s.x0, x1 = s.kind === 'circle' ? s.cx + s.r : s.x1;
314	  const z0 = s.kind === 'circle' ? s.cz - s.r : s.z0, z1 = s.kind === 'circle' ? s.cz + s.r : s.z1;
315	  const ix0 = Math.floor(x0 / STC), ix1 = Math.floor(x1 / STC), iz0 = Math.floor(z0 / STC), iz1 = Math.floor(z1 / STC);
316	  if ((ix1 - ix0 + 1) * (iz1 - iz0 + 1) > ST_BIG) { idx.big.push(i); return; }
317	  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
318	    const k = stKey(ix, iz); let list = idx.cells.get(k);
319	    if (!list) { list = []; idx.cells.set(k, list); }
320	    list.push(i);
321	  }
322	}
