324	export function stMakeMap(zones: StZone[], solids: StSolid[], radius: number): StMap {
325	  const map: StMapI = { zones, solids: [], radius, closed: new Set<string>(), idx: { cells: new Map<number, number[]>(), big: [] } };
326	  stAddSolids(map, solids);
327	  return map;
328	}
