330	/* Thêm vật cản lúc chạy (nhà thu từ cảnh, Task 6); lưới cập nhật theo */
331	export function stAddSolids(map: StMap, more: StSolid[]): void {
332	  const idx = (map as StMapI).idx;
333	  for (const s of more) { map.solids.push(s); stIndexOne(idx, s, map.solids.length - 1); }
334	}
