340	export function stZoneAt(map: StMap, x: number, z: number): StZone | null {
341	  const zs = map.zones;
342	  for (let i = 0; i < zs.length; i++) {
343	    const zn = zs[i];
344	    if (x < zn.x0 || x > zn.x1 || z < zn.z0 || z > zn.z1) continue;
345	    if (zn.gate !== undefined && map.closed.has(zn.gate)) continue;
346	    return zn;
347	  }
348	  return null;
349	}
