356	/* Hình tròn tâm (x, z) bán kính R có chạm vật cản s không (khoảng cách < R) */
357	function stHitOne(s: StSolid, x: number, z: number, R: number, feet: number): boolean {
358	  if (s.top !== undefined && feet >= s.top) return false;   // chân đã cao hơn tường thấp
359	  if (s.kind === 'circle') { const ddx = x - s.cx, ddz = z - s.cz, rr = s.r + R; return ddx * ddx + ddz * ddz < rr * rr; }
360	  const ddx = s.x0 - x > 0 ? s.x0 - x : x - s.x1 > 0 ? x - s.x1 : 0;
361	  const ddz = s.z0 - z > 0 ? s.z0 - z : z - s.z1 > 0 ? z - s.z1 : 0;
362	  return ddx * ddx + ddz * ddz < R * R;
363	}
