365	/* Có vật cản nào trong bán kính map.radius quanh (x, z) không — chỉ tra các ô lưới phủ hình tròn + danh sách lớn */
366	function stHit(map: StMap, x: number, z: number, feet: number): boolean {
367	  const idx = (map as StMapI).idx, sol = map.solids, R = map.radius;
368	  const big = idx.big;
369	  for (let i = 0; i < big.length; i++) if (stHitOne(sol[big[i]], x, z, R, feet)) return true;
370	  const ix0 = Math.floor((x - R) / STC), ix1 = Math.floor((x + R) / STC), iz0 = Math.floor((z - R) / STC), iz1 = Math.floor((z + R) / STC);
371	  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
372	    const list = idx.cells.get(stKey(ix, iz));
373	    if (!list) continue;
374	    for (let i = 0; i < list.length; i++) if (stHitOne(sol[list[i]], x, z, R, feet)) return true;
375	  }
376	  return false;
377	}
