379	/* feet: độ cao chân trên cao độ đứng, m; Infinity = bỏ qua mọi tường thấp */
380	export function stValid(map: StMap, x: number, z: number, feet: number): boolean {
381	  return stZoneAt(map, x, z) !== null && !stHit(map, x, z, feet);
382	}
