 55	let selfSlot = ST_SOLO_AVATAR;   // instance nhân vật của mình: slot đi dạo khi có chỗ, giữ nguyên khi mất kết nối (màu áo không đổi)
 56	let watching = false;        // đang xem người khác đi dạo (hết chỗ hoặc vừa nhường chỗ): không có nhân vật của mình, không đọc phím
 57	let touch: ReturnType<typeof stTouchBind> | null = null;   // điều khiển cảm ứng (setupStroll dựng)
 58	let chased = false;          // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
 59	const camS: StCam = { yaw: 0, pitch: CONFIG.stroll.cam.pitch };
 60	const _inp: StInput = { mx: 0, mz: 0, run: false, camYaw: 0 };   // đầu vào tái dùng mỗi khung
 61	
 62	const active = () => cam.mode === 'stroll' && state !== null;
 63	const inMode = () => active() || watching;   // Esc và giao diện đi dạo áp cho cả chế độ xem
 64	/* Chụp ảnh (nút 📷, phím P): giơ tay (dáng 4, tới người khác qua gói vị trí kế tiếp), chớp màn hình, xếp yêu cầu chụp cho sau lệnh vẽ */
 65	let flashTimer = 0;
 66	function stPhoto(): void {
 67	  if (!active()) return;
 68	  stPhotoPose(state!);
 69	  const f = document.getElementById('stFlash');
 70	  if (f) { f.classList.add('on'); clearTimeout(flashTimer); flashTimer = window.setTimeout(() => f.classList.remove('on'), CONFIG.stroll.flashMs); }
 71	  stPhotoRequest();
 72	}
 73	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
 74	
 75	/* Một bước: cổng nhịp quay, chuyển động, nhân vật, camera, hiệu ứng đêm, người chơi khác */
 76	function advance(dt: number, inp: StInput): void {
 77	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
 78	  stStep(state!, inp, map!, dt);
 79	  stAvatars.setSelf(selfSlot, state, dt);   // dt cho mixer của nhân vật có xương
 80	  stCamPlace(camera, controls.target, state!, camS, map!, dt);
 81	  exNightStep(dt, false);
 82	  const now = performance.now();
 83	  exMulti.update(dt, now, null);   // người khác (đi dạo + bay), nhãn tên; không làm gì khi đi một mình
 84	  exMulti.updateWalk(now, state);  // gửi vị trí + dáng khi đang giữ chỗ
 85	}
 86	
 87	/* Mỗi khung khi xem: người khác, nhãn, danh sách; camera sau lưng người được xem (hướng camera = hướng mặt họ). Không có ai thì camera giữ nguyên */
 88	function watchStep(dt: number): void {
 89	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
 90	  exMulti.update(dt, performance.now(), null);
 91	  const w = exMulti.watchWalker();
 92	  if (w) { camS.yaw = w.yaw; stCamPlace(camera, controls.target, w, camS, map!, dt, !chased); chased = true; }
 93	  exNightStep(dt, false);
 94	}
 95	
 96	/* Đổi phiên khi đang xem hoặc đang đi: vào đi, mất kết nối, bị thu hồi chỗ (như onMultiChange của dù lượn) */
 97	function stOnMultiChange(): void {
 98	  const s = exMulti.session; if (!s) return;
 99	  if (watching) {
100	    if (s.phase === 'flying') { stroll.start(); return; }   // chấp nhận lời mời: xuất phát như vào đi thường
101	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lostWalk'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện stLostChooser (nhắc Đi dạo, không phải Dù lượn)
102	    exWatchRender();
103	  } else if (active()) {
104	    if (s.phase === 'watching') { state = null; stAvatars.setSelf(selfSlot, null); stroll.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
105	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'stLost');   // vẫn đi, người khác đã biến mất
106	  }
107	}
108	
109	/* Bản đồ dựng lần đầu vào chế độ (đi hoặc xem); cổng nhịp quay theo cầu hiện tại */
110	function stEnsureMap(): StMap {
111	  if (!map) { map = stBuildStaticMap(); stCollectRuntime(map); }
112	  if (ctrl) stSetGate(map, ST_GATE_SWING, ctrl.state !== 'CLOSED');
113	  return map;
114	}
115	
116	export const stroll = {
117	  active,
118	  inMode,
119	  get watching(): boolean { return watching; },
120	  get state(): StState | null { return state; },
121	  get map(): StMap | null { return map; },
122	  get cam(): StCam { return camS; },
123	  /* Vào đi: một mình (không phiên / ngoại tuyến) hoặc với slot đi dạo vừa được cấp (xuất phát lệch theo slot) */
124	  start(): void {
125	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
126	    const m = stEnsureMap(), s = exMulti.session;
127	    const slot = s && s.kind === 'walk' && s.mySlot >= 0 ? s.mySlot : ST_SOLO_SLOT;
128	    if (s) exMulti.onChange = stOnMultiChange;
129	    selfSlot = slot >= 0 ? slot : ST_SOLO_AVATAR;
130	    state = stCreate(m, slot);
131	    camS.yaw = state.yaw; camS.pitch = CONFIG.stroll.cam.pitch;
132	    const mesh = stAvatars.build();
133	    if (!mesh.parent) scene.add(mesh);
134	    stAvatars.setSelf(selfSlot, state);
135	    keys.clear(); if (touch) touch.reset();
136	    cam.flight.then = null; cam.mode = 'stroll'; controls.enabled = false;
137	    stCamPlace(camera, controls.target, state, camS, m, 0, true);
138	    document.body.classList.add('explore', 'stroll');
139	  },
140	  /* Chế độ xem: cam.mode = 'stroll' nhưng không có nhân vật của mình; carry = true khi vừa nhường chỗ (camera đang ở sau lưng mình, trượt dần sang người được xem) */
141	  startWatching(carry = false): void {
142	    const s = exMulti.session; if (!s) return;
143	    stEnsureMap();
144	    const mesh = stAvatars.build();
145	    if (!mesh.parent) scene.add(mesh);
146	    watching = true; chased = carry; state = null;
147	    keys.clear();
148	    camS.pitch = CONFIG.stroll.cam.pitch;
149	    cam.flight.then = null; cam.mode = 'stroll'; controls.enabled = false;
150	    document.body.classList.add('explore', 'stroll', 'ex-watching');
151	    exMulti.onChange = stOnMultiChange;
152	    exWatchShow(s);
153	  },
154	  update(dt: number): void {
155	    if (watching) { watchStep(dt); return; }
156	    if (!active()) return;
157	    stInputFromKeys(keys, camS.yaw, _inp);
158	    if (touch) touch.read(_inp);   // cần gạt đang giữ thì ghi đè hướng và chạy của phím
159	    advance(dt, _inp);
160	  },
161	  photo: stPhoto,
162	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts): chụp canvas nếu có yêu cầu */
163	  afterRender(): void { stPhotoAfterRender(canvas); },
164	  get photoLast() { return stPhotoLast; },
165	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
166	  step(dt: number, inp: StInput): void {
167	    if (active()) advance(dt, inp);
168	  }
169	};
170	
171	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
172	export function setupStroll(c: SwingController, onExit: () => void): void {
173	  ctrl = c; exit = onExit;
174	  window.addEventListener('keydown', (e) => {
175	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung); đang xem: không đọc phím
176	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển nhân vật, tránh kẹt phím
177	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển nhân vật
178	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
179	    const k = stKeyName(e);   // theo vị trí phím (e.code): bố cục không Latin (ru, ar, th, hi) vẫn dùng WASD
180	    if (k === 'p') { if (!e.repeat) stPhoto(); return; }   // P chụp ảnh, không ghi vào keys
181	    if (k === ' ') { e.preventDefault(); return; }   // Space: không cuộn trang, không bấm nút đang focus, không điều khiển gì
182	    if (k.startsWith('arrow')) e.preventDefault();
183	    keys.add(k);
184	  });
185	  window.addEventListener('keyup', (e) => {
186	    const k = stKeyName(e);
187	    keys.delete(k); keys.delete(e.key.toLowerCase());   // cả tên cũ: phím dù lượn ghi theo e.key
188	    if (k === ' ' && active() && !isField(e.target)) e.preventDefault();   // Space không bấm nút đang focus
189	  });
190	  const drop = () => { keys.clear(); };
191	  window.addEventListener('blur', drop);
192	  document.addEventListener('visibilitychange', () => { if (document.hidden) drop(); });
193	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) drop(); });
194	  const hud = document.getElementById('stHud');
195	  if (hud) touch = stTouchBind(hud, {
196	    look: (dx, dy) => { if (active()) stCamDrag(camS, dx, dy, CONFIG.stroll.cam.touch); },
197	    photo: stPhoto,
198	    activity: () => exMulti.activity()
199	  });
200	  /* Kéo chuột trái trên canvas: xoay camera (cảm ứng ở Task 8) */
201	  let dragId = -1, lx = 0, ly = 0;
202	  canvas.addEventListener('pointerdown', (e) => {
203	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
204	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
205	    canvas.setPointerCapture(e.pointerId);
206	  });
207	  canvas.addEventListener('pointermove', (e) => {
208	    if (e.pointerId !== dragId) return;
209	    stCamDrag(camS, e.clientX - lx, e.clientY - ly, CONFIG.stroll.cam.mouse);
210	    exMulti.activity();   // xoay camera cũng tính là còn đó
211	    lx = e.clientX; ly = e.clientY;
212	  });
213	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
214	  canvas.addEventListener('pointerup', end);
215	  canvas.addEventListener('pointercancel', end);
216	  canvas.addEventListener('lostpointercapture', end);
217	}
218	/* ============================ Đi dạo: chuyển động nhân vật (thuần) ============================
219	   Mỗi khung: đọc đầu vào, đổi tốc độ / hướng mặt, đi qua stMove (va chạm), bám cao độ đứng, chọn dáng (pose).
220	   Thuần: không import three, không đụng DOM. stStep chạy mỗi khung nên không cấp phát (D-018): dùng đối tượng tạm cấp module.
221	   - dt kẹp về dtMax: khung rất dài (tab ẩn rồi quay lại) không làm nhân vật vọt qua tường, chỉ chậm đi một khung.
222	   - Hướng: tới = (cos yaw, 0, −sin yaw), yaw tăng là quay trái (như flight.ts).
223	   - Cổng nhịp quay đóng dưới chân (vị trí không còn hợp lệ): stMove đóng băng khi điểm xuất phát không hợp lệ, nên sơ tán KHÔNG dùng stMove:
224	     tính một lần điểm hợp lệ gần nhất (stNearestValid, đắt), rồi đi thẳng tới đó với tốc độ chạy, bỏ qua đầu vào; tới nơi thì trả điều khiển. */
225	import { CONFIG } from '../../config';
226	import { stMove, stValid, stGroundY, stNearestValid, type StMap } from './map';
227	import { stSpawn } from './mapData';
228	
229	export const ST_POSE_IDLE = 0, ST_POSE_WALK = 1, ST_POSE_RUN = 2, ST_POSE_FALL = 3, ST_POSE_PHOTO = 4;   // 3 = rơi (trên mạng giữ giá trị cũ của dáng nhảy; khách bản cũ còn gửi 3 khi nhảy)
230	
231	export interface StState {
232	  x: number; y: number; z: number;   // y: cao độ chân tuyệt đối, m
233	  yaw: number; speed: number;        // speed: tốc độ mặt bằng, m/s
234	  vy: number; air: boolean;          // vy: vận tốc đứng, m/s
235	  pose: number; evac: boolean;
236	  photo: number;                     // giây còn giơ tay chụp
237	  tx: number; tz: number;            // điểm sơ tán đã tính (chỉ có nghĩa khi evac)
238	}
239	export interface StInput { mx: number; mz: number; run: boolean; camYaw: number }
240	
241	const EPS_STEP = 1e-3;      // dung sai khi so bậc cao độ với stepMax (bậc Cầu Rồng lề ↔ bờ đo 0,3500083), m
242	const V_STOP = 0.1;         // m/s — dưới mức này coi là đứng yên
243	const _mv = { x: 0, z: 0 };      // kết quả stMove
244	const _near = { x: 0, z: 0 };    // kết quả stNearestValid
245	
246	export function stCreate(map: StMap, slot: number): StState {
247	  const p = { x: 0, z: 0 };
248	  stSpawn(map, slot, p);
249	  const g = stGroundY(map, p.x, p.z);
250	  return { x: p.x, y: g === g ? g : CONFIG.roadY, z: p.z, yaw: CONFIG.stroll.spawnYaw, speed: 0, vy: 0, air: false, pose: ST_POSE_IDLE, evac: false, photo: 0, tx: p.x, tz: p.z };
251	}
252	
253	export function stPhotoPose(s: StState): void { s.photo = CONFIG.stroll.photoHold; }
254	
255	/* quay yaw về đích theo đường ngắn nhất, tốc độ mũ turn (1/s) */
256	function stTurn(yaw: number, target: number, turn: number, dt: number): number {
257	  let d = (target - yaw) % (2 * Math.PI);
258	  if (d > Math.PI) d -= 2 * Math.PI; else if (d < -Math.PI) d += 2 * Math.PI;
259	  const k = turn * dt;
260	  return yaw + d * (k < 1 ? k : 1);
261	}
262	
263	/* Sơ tán: đi thẳng tới (tx, tz) với tốc độ chạy, mỗi khung không quá run × dt */
264	function stEvacStep(s: StState, map: StMap, dt: number): void {
265	  const C = CONFIG.stroll, dx = s.tx - s.x, dz = s.tz - s.z, dist = Math.sqrt(dx * dx + dz * dz), step = C.run * dt;
266	  s.photo = 0; s.speed = C.run; s.pose = ST_POSE_RUN;
267	  if (dist > 1e-9) s.yaw = stTurn(s.yaw, Math.atan2(-dz, dx), C.turn, dt);
268	  if (dist <= step) { s.x = s.tx; s.z = s.tz; s.evac = false; s.speed = 0; s.pose = ST_POSE_IDLE; }
269	  else { s.x += dx / dist * step; s.z += dz / dist * step; }
270	  const g = stGroundY(map, s.x, s.z);
271	  if (g === g) s.y = g;                                  // ngoài mọi vùng (cổng đóng): giữ cao độ cũ
272	  s.air = false; s.vy = 0;
273	}
274	
275	export function stStep(s: StState, inp: StInput, map: StMap, dt: number): void {
276	  const C = CONFIG.stroll;
277	  if (!(dt > 0)) return;
278	  if (dt > C.dtMax) dt = C.dtMax;
279	
280	  /* 1) vị trí không còn hợp lệ với tường cao / vùng (tường thấp không tính: đáp xuống giữa tường thấp là chuyện của stMove) */
281	  if (!s.evac && !stValid(map, s.x, s.z, Infinity)) {
282	    s.evac = true;
283	    if (!stNearestValid(map, s.x, s.z, _near)) stSpawn(map, -1, _near);
284	    s.tx = _near.x; s.tz = _near.z;
285	  }
286	  if (s.evac) { stEvacStep(s, map, dt); return; }
287	
288	  /* 2) hướng đi và tốc độ đích */
289	  const sc = Math.sin(inp.camYaw), cc = Math.cos(inp.camYaw);
290	  const dx = inp.mz * cc + inp.mx * sc, dz = -inp.mz * sc + inp.mx * cc;
291	  let len = Math.sqrt(dx * dx + dz * dz);
292	  const moving = len > 1e-6;
293	  if (len > 1) len = 1;
294	  const target = moving ? (inp.run ? C.run : C.walk) * len : 0;
295	  const da = C.accel * dt;
296	  if (s.speed < target) s.speed = s.speed + da < target ? s.speed + da : target;
297	  else s.speed = s.speed - da > target ? s.speed - da : target;
298	  let hx: number, hz: number;                            // hướng di chuyển: theo đầu vào; thả tay thì trượt theo hướng mặt đang hãm
299	  if (moving) { hx = dx / Math.sqrt(dx * dx + dz * dz); hz = dz / Math.sqrt(dx * dx + dz * dz); s.yaw = stTurn(s.yaw, Math.atan2(-hz, hx), C.turn, dt); }
300	  else { hx = Math.cos(s.yaw); hz = -Math.sin(s.yaw); }
301	
302	  /* 3) đi (feet: độ cao chân trên cao độ đứng chỗ đang đứng) */
303	  const g0 = stGroundY(map, s.x, s.z);
304	  const feet = s.air && g0 === g0 ? Math.max(0, s.y - g0) : 0;
305	  const dist = s.speed * dt;
306	  stMove(map, s.x, s.z, hx * dist, hz * dist, feet, _mv);
307	  s.x = _mv.x; s.z = _mv.z;
308	
309	  /* 4) cao độ */
310	  const g = stGroundY(map, s.x, s.z);
311	  if (s.air) {
312	    const ny = s.y + s.vy * dt - 0.5 * C.gravity * dt * dt;
313	    s.vy -= C.gravity * dt;
314	    if (g === g && ny <= g) {                            // chạm đất
315	      s.y = g; s.vy = 0; s.air = false;
316	      if (!stValid(map, s.x, s.z, 0) && stNearestValid(map, s.x, s.z, _near)) { s.x = _near.x; s.z = _near.z; const g2 = stGroundY(map, s.x, s.z); if (g2 === g2) s.y = g2; }   // đáp giữa tường thấp: đẩy ra mép gần nhất
317	    } else s.y = ny;
318	  } else if (g === g) {
319	    if (s.y - g > C.stepMax + EPS_STEP) { s.air = true; s.vy = 0; }   // bước xuống quá bậc: rơi
320	    else s.y = g;
321	  }
322	
323	  /* 5) dáng */
324	  if (s.photo > 0) { if (moving || s.air) s.photo = 0; else { s.photo -= dt; if (s.photo < 0) s.photo = 0; } }
325	  const still = s.speed < V_STOP && !moving;
326	  if (s.air) s.pose = ST_POSE_FALL;
327	  else if (s.photo > 0 && still) s.pose = ST_POSE_PHOTO;
328	  else if (s.speed < V_STOP) s.pose = ST_POSE_IDLE;
329	  else s.pose = s.speed > (C.walk + C.run) * 0.5 ? ST_POSE_RUN : ST_POSE_WALK;
330	}

