 16	interface StMapI extends StMap { idx: StIndex }
 17	
 18	const STC = 16;          // cạnh ô lưới, m (nhà ven sông 10–40 m, mỗi nhà phủ vài ô)
 19	const ST_BIG = 64;       // vật cản phủ hơn số ô này thì vào danh sách "lớn"
 20	const ST_OFF = 32768;    // dời chỉ số ô về số dương để ghép khóa (đủ cho ±524 km)
 21	const stKey = (ix: number, iz: number): number => (ix + ST_OFF) * 65536 + (iz + ST_OFF);
 22	
 23	/* Thêm một vật cản (chỉ số i trong map.solids) vào lưới theo hộp bao của nó */
 24	function stIndexOne(idx: StIndex, s: StSolid, i: number): void {
 25	  const x0 = s.kind === 'circle' ? s.cx - s.r : s.x0, x1 = s.kind === 'circle' ? s.cx + s.r : s.x1;
 26	  const z0 = s.kind === 'circle' ? s.cz - s.r : s.z0, z1 = s.kind === 'circle' ? s.cz + s.r : s.z1;
 27	  const ix0 = Math.floor(x0 / STC), ix1 = Math.floor(x1 / STC), iz0 = Math.floor(z0 / STC), iz1 = Math.floor(z1 / STC);
 28	  if ((ix1 - ix0 + 1) * (iz1 - iz0 + 1) > ST_BIG) { idx.big.push(i); return; }
 29	  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
 30	    const k = stKey(ix, iz); let list = idx.cells.get(k);
 31	    if (!list) { list = []; idx.cells.set(k, list); }
 32	    list.push(i);
 33	  }
 34	}
 35	
 36	export function stMakeMap(zones: StZone[], solids: StSolid[], radius: number): StMap {
 37	  const map: StMapI = { zones, solids: [], radius, closed: new Set<string>(), idx: { cells: new Map<number, number[]>(), big: [] } };
 38	  stAddSolids(map, solids);
 39	  return map;
 40	}
 41	
 42	/* Thêm vật cản lúc chạy (nhà thu từ cảnh, Task 6); lưới cập nhật theo */
 43	export function stAddSolids(map: StMap, more: StSolid[]): void {
 44	  const idx = (map as StMapI).idx;
 45	  for (const s of more) { map.solids.push(s); stIndexOne(idx, s, map.solids.length - 1); }
 46	}
 47	
 48	export function stSetGate(map: StMap, gate: string, closed: boolean): void {
 49	  if (closed) map.closed.add(gate); else map.closed.delete(gate);
 50	}
 51	
 52	export function stZoneAt(map: StMap, x: number, z: number): StZone | null {
 53	  const zs = map.zones;
 54	  for (let i = 0; i < zs.length; i++) {
 55	    const zn = zs[i];
 56	    if (x < zn.x0 || x > zn.x1 || z < zn.z0 || z > zn.z1) continue;
 57	    if (zn.gate !== undefined && map.closed.has(zn.gate)) continue;
 58	    return zn;
 59	  }
 60	  return null;
 61	}
 62	
 63	export function stGroundY(map: StMap, x: number, z: number): number {
 64	  const zn = stZoneAt(map, x, z);
 65	  return zn ? zn.y(x, z) : NaN;
 66	}
 67	
 68	/* Hình tròn tâm (x, z) bán kính R có chạm vật cản s không (khoảng cách < R) */
 69	function stHitOne(s: StSolid, x: number, z: number, R: number, feet: number): boolean {
 70	  if (s.top !== undefined && feet >= s.top) return false;   // chân đã cao hơn tường thấp
 71	  if (s.kind === 'circle') { const ddx = x - s.cx, ddz = z - s.cz, rr = s.r + R; return ddx * ddx + ddz * ddz < rr * rr; }
 72	  const ddx = s.x0 - x > 0 ? s.x0 - x : x - s.x1 > 0 ? x - s.x1 : 0;
 73	  const ddz = s.z0 - z > 0 ? s.z0 - z : z - s.z1 > 0 ? z - s.z1 : 0;
 74	  return ddx * ddx + ddz * ddz < R * R;
 75	}
 76	
 77	/* Có vật cản nào trong bán kính map.radius quanh (x, z) không — chỉ tra các ô lưới phủ hình tròn + danh sách lớn */
 78	function stHit(map: StMap, x: number, z: number, feet: number): boolean {
 79	  const idx = (map as StMapI).idx, sol = map.solids, R = map.radius;
 80	  const big = idx.big;
 81	  for (let i = 0; i < big.length; i++) if (stHitOne(sol[big[i]], x, z, R, feet)) return true;
 82	  const ix0 = Math.floor((x - R) / STC), ix1 = Math.floor((x + R) / STC), iz0 = Math.floor((z - R) / STC), iz1 = Math.floor((z + R) / STC);
 83	  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
 84	    const list = idx.cells.get(stKey(ix, iz));
 85	    if (!list) continue;
 86	    for (let i = 0; i < list.length; i++) if (stHitOne(sol[list[i]], x, z, R, feet)) return true;
 87	  }
 88	  return false;
 89	}
 90	
 91	/* feet: độ cao chân trên cao độ đứng, m; Infinity = bỏ qua mọi tường thấp */
 92	export function stValid(map: StMap, x: number, z: number, feet: number): boolean {
 93	  return stZoneAt(map, x, z) !== null && !stHit(map, x, z, feet);
 94	}
 95	
 96	/* Đi (dx, dz) từ (x, z), kết quả vào out. Chia bước con ≤ radius / 2 nên vật cản phồng theo bán kính (dày ≥ 2·radius) không thể bị nhảy qua.
 97	   Mỗi bước con: thử cả hai trục, rồi chỉ x, rồi chỉ z (trượt dọc tường), không được thì dừng.
 98	   Điểm xuất phát nằm trong tường thấp (vừa đáp xuống giữa tường) thì bước này bỏ qua tường thấp để thoát ra, không bị kẹt. */
 99	export function stMove(map: StMap, x: number, z: number, dx: number, dz: number, feet: number, out: { x: number; z: number }): void {
100	  let cx = x, cz = z;
101	  const len = Math.sqrt(dx * dx + dz * dz);
102	  if (len > 0) {
103	    const f = !stValid(map, x, z, feet) && stValid(map, x, z, Infinity) ? Infinity : feet;
104	    const n = Math.max(1, Math.ceil(len / (map.radius * 0.5)));
105	    const sx = dx / n, sz = dz / n;
106	    for (let i = 0; i < n; i++) {
107	      if (stValid(map, cx + sx, cz + sz, f)) { cx += sx; cz += sz; }
108	      else if (sx !== 0 && stValid(map, cx + sx, cz, f)) cx += sx;
109	      else if (sz !== 0 && stValid(map, cx, cz + sz, f)) cz += sz;
110	      else break;
111	    }
112	  }
113	  out.x = cx; out.z = cz;
114	}
115	
116	/* Điểm hợp lệ gần nhất (chân trên mặt đứng, tường thấp tính là chặn): vòng tròn nở dần mỗi 0,2 m, tối đa 80 m.
117	   Dùng cho sơ tán và điểm xuất phát, không gọi mỗi khung (trường hợp xấu nhất vài triệu lần thử). */
118	const ST_NEAR_STEP = 0.2;   // bước nở vòng và khoảng cách điểm trên vòng, m
119	const ST_NEAR_MAX = 80;     // bán kính tìm tối đa, m
120	export function stNearestValid(map: StMap, x: number, z: number, out: { x: number; z: number }): boolean {
121	  if (stValid(map, x, z, 0)) { out.x = x; out.z = z; return true; }
122	  const rings = Math.round(ST_NEAR_MAX / ST_NEAR_STEP);
123	  for (let k = 1; k <= rings; k++) {
124	    const d = k * ST_NEAR_STEP, n = Math.ceil(2 * Math.PI * d / ST_NEAR_STEP);
125	    for (let j = 0; j < n; j++) {
126	      const a = j * 2 * Math.PI / n, px = x + d * Math.cos(a), pz = z + d * Math.sin(a);
127	      if (stValid(map, px, pz, 0)) { out.x = px; out.z = pz; return true; }
128	    }
129	  }
130	  return false;
131	}
132	
133	/* Tham số t (0..1) nơi đoạn a + t·d đi vào vật cản s (hình thật, không phồng theo bán kính); 2 = không chạm */
134	function stSegEnter(s: StSolid, ax: number, az: number, dx: number, dz: number): number {
135	  if (s.kind === 'circle') {
136	    const fx = ax - s.cx, fz = az - s.cz, c = fx * fx + fz * fz - s.r * s.r;
137	    if (c <= 0) return 0;                                   // xuất phát trong cột
138	    const a = dx * dx + dz * dz, b = 2 * (fx * dx + fz * dz);
139	    if (a === 0) return 2;
140	    const disc = b * b - 4 * a * c;
141	    if (disc < 0) return 2;
142	    const t = (-b - Math.sqrt(disc)) / (2 * a);
143	    return t >= 0 && t <= 1 ? t : 2;
144	  }
145	  let tmin = -Infinity, tmax = Infinity;
146	  if (dx === 0) { if (ax < s.x0 || ax > s.x1) return 2; }
147	  else { let t1 = (s.x0 - ax) / dx, t2 = (s.x1 - ax) / dx; if (t1 > t2) { const q = t1; t1 = t2; t2 = q; } if (t1 > tmin) tmin = t1; if (t2 < tmax) tmax = t2; }
148	  if (dz === 0) { if (az < s.z0 || az > s.z1) return 2; }
149	  else { let t1 = (s.z0 - az) / dz, t2 = (s.z1 - az) / dz; if (t1 > t2) { const q = t1; t1 = t2; t2 = q; } if (t1 > tmin) tmin = t1; if (t2 < tmax) tmax = t2; }
150	  if (tmax < tmin || tmax < 0 || tmin > 1) return 2;
151	  return tmin > 0 ? tmin : 0;
152	}
153	
154	/* Phần (0..1) của đoạn a→b đi được trước khi chạm vật cản cao vô hạn hoặc ra khỏi mọi vùng mở (cho camera). Không cấp phát. */
155	const ST_EPS = 1e-7;   // dung sai khi xét điểm nằm trên cạnh chung hai vùng, m
156	export function stSegClear(map: StMap, ax: number, az: number, bx: number, bz: number): number {
157	  const dx = bx - ax, dz = bz - az;
158	  /* 1) vùng: đi theo chuỗi vùng mở chứa điểm hiện tại, mỗi lần nhảy tới chỗ ra xa nhất */
159	  let t = 0, tz = 0;
160	  for (let it = 0; it < 64; it++) {
161	    const px = ax + dx * t, pz = az + dz * t;
162	    let best = -1;
163	    for (let i = 0; i < map.zones.length; i++) {
164	      const zn = map.zones[i];
165	      if (px < zn.x0 - ST_EPS || px > zn.x1 + ST_EPS || pz < zn.z0 - ST_EPS || pz > zn.z1 + ST_EPS) continue;
166	      if (zn.gate !== undefined && map.closed.has(zn.gate)) continue;
167	      const ex = dx > 0 ? (zn.x1 - ax) / dx : dx < 0 ? (zn.x0 - ax) / dx : Infinity;
168	      const ez = dz > 0 ? (zn.z1 - az) / dz : dz < 0 ? (zn.z0 - az) / dz : Infinity;
169	      const e = ex < ez ? ex : ez;
170	      if (e > best) best = e;
171	    }
172	    if (best < 0) { tz = t; break; }                        // không vùng nào chứa điểm (chỉ xảy ra khi xuất phát ngoài vùng)
173	    if (best >= 1) { tz = 1; break; }
174	    if (best <= t + 1e-9) { tz = t; break; }                // không vùng nào đi tiếp được
175	    t = best; tz = t;
176	  }
177	  /* 2) vật cản cao vô hạn trong hộp bao đoạn; hộp quá lớn thì quét hết */
178	  let ts = tz;
179	  const sol = map.solids, idx = (map as StMapI).idx;
180	  const ix0 = Math.floor(Math.min(ax, bx) / STC), ix1 = Math.floor(Math.max(ax, bx) / STC), iz0 = Math.floor(Math.min(az, bz) / STC), iz1 = Math.floor(Math.max(az, bz) / STC);
181	  if ((ix1 - ix0 + 1) * (iz1 - iz0 + 1) > sol.length) {
182	    for (let i = 0; i < sol.length; i++) { const s = sol[i]; if (s.top !== undefined) continue; const e = stSegEnter(s, ax, az, dx, dz); if (e < ts) ts = e; }
183	    return ts;
184	  }
185	  const big = idx.big;
186	  for (let i = 0; i < big.length; i++) { const s = sol[big[i]]; if (s.top !== undefined) continue; const e = stSegEnter(s, ax, az, dx, dz); if (e < ts) ts = e; }
187	  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
188	    const list = idx.cells.get(stKey(ix, iz));
189	    if (!list) continue;
190	    for (let i = 0; i < list.length; i++) { const s = sol[list[i]]; if (s.top !== undefined) continue; const e = stSegEnter(s, ax, az, dx, dz); if (e < ts) ts = e; }
191	  }
192	  return ts;
193	}
194	/* ============================ Đi dạo: vật cản thu từ cảnh đã dựng ============================
195	   Gọi MỘT lần, lần đầu vào chế độ (sau khi mọi bước dọn nhà đã chạy): chỉ đọc cảnh, không đụng chuỗi rand() hay thứ tự dựng (spec §6).
196	   - Nhà đang hiện (collectBuildings: level gần của THREE.LOD, bỏ instance scale 0) có chân đế chạm khung CONFIG.stroll.bounds: chữ nhật thẳng trục (nhà không xoay, city.ts).
197	   - Chân đế địa danh và pano ven sông (riverfront footprints), trừ chân đế có tâm trong vùng `love`: Cầu Tình Yêu đi được, lan can / tượng đã dựng riêng ở mapData.ts.
198	   Vật cản hỏng (số không hữu hạn, rộng ≤ 0) thì bỏ và đếm: lõi bản đồ không lập chỉ mục được nhưng stSegClear vẫn thấy, nên không được lọt vào. */
199	import { CONFIG } from '../../config';
200	import { collectBuildings, type Rect } from '../../environment/riverfront/clearance';
201	import { getRiverfront } from '../../environment/riverfront';
202	import { stAddSolids, type StMap, type StSolid } from './map';
203	
204	export const stSceneStats = { buildings: 0, footprints: 0, skipped: 0 };
205	
206	const stGood = (r: Rect): boolean => Number.isFinite(r.x0) && Number.isFinite(r.x1) && Number.isFinite(r.z0) && Number.isFinite(r.z1) && r.x1 > r.x0 && r.z1 > r.z0;
207	
208	export function stCollectRuntime(map: StMap): number {
209	  const B = CONFIG.stroll.bounds, out: StSolid[] = [];
210	  let nb = 0, nf = 0, bad = 0;
211	  for (const b of collectBuildings()) {
212	    const r = { x0: b.x - b.w / 2, x1: b.x + b.w / 2, z0: b.z - b.d / 2, z1: b.z + b.d / 2 };
213	    if (!stGood(r)) { bad++; continue; }
214	    if (r.x1 < B.x0 || r.x0 > B.x1 || r.z1 < B.z0 || r.z0 > B.z1) continue;
215	    out.push({ kind: 'rect', ...r }); nb++;
216	  }
217	  const love = map.zones.find((z) => z.id === 'love');
218	  for (const f of getRiverfront()?.footprints ?? []) {
219	    if (!stGood(f)) { bad++; continue; }
220	    const cx = (f.x0 + f.x1) / 2, cz = (f.z0 + f.z1) / 2;
221	    if (love && cx >= love.x0 && cx <= love.x1 && cz >= love.z0 && cz <= love.z1) continue;
222	    out.push({ kind: 'rect', x0: f.x0, x1: f.x1, z0: f.z0, z1: f.z1 }); nf++;
223	  }
224	  if (bad) console.warn(`[stroll] bỏ ${bad} vật cản hỏng khi thu từ cảnh`);
225	  stSceneStats.buildings = nb; stSceneStats.footprints = nf; stSceneStats.skipped = bad;
226	  stAddSolids(map, out);
227	  return out.length;
228	}

