 1	/* ============================ Tự khám phá: màn chọn phương tiện ============================
 2	   Lớp phủ HTML (#chooser trong index.html), không thêm gì vào cảnh. Hiện sau khung đầu tiên (cảnh đã dựng phía sau)
 3	   và chặn chuột vào canvas tới khi chọn. Chữ do data-i18n lo; ở đây chỉ khóa thẻ và gọi onPick. */
 4	
 5	import { getLang, onChange, t } from '../i18n';
 6	import { exMulti } from './multi';
 7	import { exShowLobby } from './multi/lobby';
 8	
 9	export type ExChoice = 'glider' | 'guided' | 'walk';
10	
11	const el = () => document.getElementById('chooser');
12	
13	/* Dù lượn cần bàn phím: thiết bị cảm ứng (không có hover) thì khóa thẻ và hiện nhãn "Chỉ dùng trên máy tính". Thẻ Đi dạo không khóa (có điều khiển cảm ứng) */
14	function lockGliderOnTouch(root: HTMLElement): void {
15	  if (!window.matchMedia('(hover: none)').matches) return;
16	  const card = root.querySelector<HTMLButtonElement>('[data-pick="glider"]');
17	  if (!card) return;
18	  card.disabled = true;
19	  card.querySelector<HTMLElement>('.ex-note')?.removeAttribute('hidden');
20	}
21	
22	/* Ô ngôn ngữ riêng của màn chọn (lớp phủ che #langSelect): chép danh sách từ #langSelect, đổi thì chuyển cho #langSelect xử lý */
23	function wireLang(root: HTMLElement): void {
24	  const mine = root.querySelector<HTMLSelectElement>('#exLang');
25	  const main = document.getElementById('langSelect') as HTMLSelectElement | null;
26	  if (!mine || !main) return;
27	  mine.innerHTML = main.innerHTML; mine.value = getLang();
28	  mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
29	  onChange((code) => { mine.value = code; });
30	}
31	
32	/* Màn chọn là hộp thoại modal: các khối giao diện cũ (header, panel, canvas...) đặt inert để Tab/Enter không lọt xuống dưới */
33	const inerted: HTMLElement[] = [];
34	function setUnderInert(root: HTMLElement, on: boolean): void {
35	  if (on) {
36	    for (const c of Array.from(document.body.children) as HTMLElement[]) {
37	      if (c === root || c.tagName === 'SCRIPT' || c.id === 'loading' || c.inert) continue;
38	      c.inert = true; inerted.push(c);
39	    }
40	  } else { for (const c of inerted) c.inert = false; inerted.length = 0; }
41	}
42	
43	export function exShowChooser(onPick: (choice: ExChoice) => void, onWatch: (choice: ExChoice) => void = () => {}): void {
44	  const root = el();
45	  if (!root) return;
46	  lockGliderOnTouch(root);
47	  /* Lần trước mất kết nối khi đang xem (explore.exit tải lại trang): đọc cờ một lần rồi xóa, hiện exMpLostChooser */
48	  try {
49	    const lost = sessionStorage.getItem('exMpNotice');   // 'lost' (xem bầu trời dù lượn) | 'lostWalk' (xem người đi dạo: câu nhắc chọn Đi dạo, vì thẻ Dù lượn bị khóa trên điện 
50	    if (lost === 'lost' || lost === 'lostWalk') { sessionStorage.removeItem('exMpNotice'); const n = document.getElementById('exMpLostNote'); if (n) { if (lost === 'lostWalk') { n.dataset.i18n = 'stLostChooser'; n
51	  } catch { /* bộ nhớ bị chặn */ }
52	  wireLang(root);
53	  /* Không dùng { once: true }: từ sảnh bấm Quay lại / Esc thì các thẻ phải chọn lại được. Hộp đã đóng (đã chọn xong) thì bỏ qua */
54	  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
55	    if (b.disabled) return;
56	    b.addEventListener('click', () => {
57	      if (root.hidden) return;
58	      const choice = b.dataset.pick as ExChoice;
59	      /* Dù lượn / Đi dạo có máy chủ: sang bước chọn slot + nhập tên (mở kết nối ở đây, không sớm hơn); không có máy chủ: bay / đi một mình ngay như trước */
60	      if ((choice === 'glider' || choice === 'walk') && exMulti.begin(() => {}, choice === 'walk' ? 'walk' : 'fly')) {
61	        const solo = () => { exHideChooser(); onPick(choice); };
62	        exShowLobby(exMulti.session!, { onFly: solo, onWatch: () => { exHideChooser(); onWatch(choice); }, onSolo: solo, onBack: () => b.focus({ preventScroll: true }) });
63	        return;
64	      }
65	      exHideChooser(); onPick(choice);
66	    });
67	  });
68	  const show = () => { root.hidden = false; setUnderInert(root, true); root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
69	  const loading = document.getElementById('loading');
70	  if (!loading || loading.classList.contains('done')) { show(); return; }
71	  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
72	  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
73	}
74	
75	export function exHideChooser(): void {
76	  const root = el();
77	  if (root) { root.hidden = true; setUnderInert(root, false); }
78	}
 1	/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
 2	import { multiParams } from './params';
