618:   Chế độ đi bộ góc nhìn sau lưng (docs/superpowers/specs/2026-11-11-di-dao-design.md). Vùng đi được dựng ở explore/stroll/mapData.ts. Mọi số đều (ước lượng) */
619:const strollBase = {
632:  bounds: { x0: -400, x1: 400, z0: -1300, z1: 220 },   // m — khung chứa mọi vùng đi được, phải bằng multiParams.stroll.bounds (có test kiểm) (ước lượng)
653:  anim: {              // nhân vật có xương (explore/stroll/anim.ts, rig.ts); docs/superpowers/specs/2026-11-12-nguoi-di-dao-that-design.md §5
655:    jogAt: 3.5,        // m/s — tại tốc độ này là chạy bộ thuần (bằng tốc độ đi CONFIG.stroll.walk) (ước lượng)
     1	/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
     2	   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
     3	   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
     4	import * as THREE from 'three';
     5	import { scene, camera, controls } from '../core/renderer';
     6	import { cam, keys } from '../views/state';
     7	import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
     8	import { exBuildGlider, exPlaceGlider } from './glider';
     9	import { exChase } from './chase';
    10	import { exShowChooser } from './chooser';
    11	import { exNight, exNightBind, exNightStep } from './nightShows';
    12	import { exMulti } from './multi';
    13	import { stroll, setupStroll } from './stroll';
    14	import { stAvatars } from './stroll/avatars';
    15	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from './multi/watch';
    16	import { CONFIG } from '../config';
    17	import type { SwingController } from '../bridges/song-han/SwingController';
    18	
    19	const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung
    20	
    21	let glider: THREE.Group | null = null;
    22	let state: GliderState | null = null;
    23	let watching = false;   // đang xem người khác bay (hết chỗ hoặc vừa nhường chỗ): không có dù của mình, không đọc phím
    24	let chased = false;     // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
    25	let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi
    26	
    27	const active = () => cam.mode === 'glider' && state !== null;
    28	const inGlider = () => active() || watching;   // Esc và giao diện bay áp cho cả chế độ xem
    29	
    30	/* Mỗi khung khi xem: dù người khác, nhãn, danh sách; camera bám dù đang xem (không có người thì giữ nguyên) */
    31	function watchStep(dt: number): void {
    32	  exMulti.update(dt, performance.now(), null);
    33	  const st = exMulti.watchState();
    34	  if (st) { exChase(camera, controls.target, st, dt, !chased); chased = true; }
    35	  exNightStep(dt);
    36	}
    37	
    38	/* Đổi phiên khi đang xem hoặc bay: vào bay, mất kết nối, bị thu hồi chỗ */
    39	function onMultiChange(): void {
    40	  const s = exMulti.session; if (!s) return;
    41	  if (watching) {
    42	    if (s.phase === 'flying') { explore.start(); return; }   // chấp nhận lời mời: cất cánh mới như bay thường
    43	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } explore.exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
    44	    exWatchRender();
    45	  } else if (active()) {
    46	    if (s.phase === 'watching') { state = null; if (glider) glider.visible = false; explore.startWatching(true); return; }   // chỗ bị thu hồi: sang xem, camera giữ nguyên
    47	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'exMpLost');   // vẫn bay, người khác đã biến mất
    48	  }
    49	}
    50	
    51	/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
    52	function exShowSpeed(): void {
    53	  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
    54	  if (t === readout) return;
    55	  readout = t;
    56	  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
    57	}
    58	
    59	/* Một bước: mô phỏng, đặt dù, đặt camera bám */
    60	function advance(dt: number, inp: GliderInput): void {
    61	  exStep(state!, inp, dt);
    62	  exPlaceGlider(glider!, state!);
    63	  exChase(camera, controls.target, state!, dt);
    64	  exShowSpeed();
    65	  exNightStep(dt);
    66	  exMulti.update(dt, performance.now(), state);   // dù người khác, nhãn tên, gửi vị trí (không làm gì khi bay một mình)
    67	}
    68	
    69	export const explore = {
    70	  active,
    71	  nightShows: exNight,
    72	  get state() { return state; },
    73	  get glider() { return glider; },
    74	  get watching() { return watching; },
    75	  start(): void {
    76	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
    77	    exMulti.onChange = onMultiChange;
    78	    state = exCreate();
    79	    const slot = exMulti.session ? exMulti.session.mySlot : -1;
    80	    if (slot >= 0) state.pos.z += CONFIG.explore.multi.spawnSpread * (slot - 2);   // mỗi slot cất cánh lệch một đoạn để không chồng nhau
    81	    if (!glider) glider = exBuildGlider();
    82	    if (!glider.parent) scene.add(glider);
    83	    glider.visible = true;
    84	    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    85	    exPlaceGlider(glider, state);
    86	    exChase(camera, controls.target, state, 0, true);
    87	    exShowSpeed();
    88	    document.body.classList.add('explore');
    89	  },
    90	  /* Chế độ xem: cam.mode = 'glider' nhưng không có state/dù của mình; carry = true khi vừa nhường chỗ (camera đang ở sau dù cũ) */
    91	  startWatching(carry = false): void {
    92	    const s = exMulti.session; if (!s) return;
    93	    watching = true; chased = carry;
    94	    keys.clear();
    95	    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    96	    document.body.classList.add('explore', 'ex-watching');
    97	    exMulti.onChange = onMultiChange;
    98	    exWatchShow(s);
    99	  },
   100	  update(dt: number): void {
   101	    if (watching) { watchStep(dt); return; }
   102	    if (!active()) return;
   103	    advance(dt, exInputFromKeys(keys, _inp));
   104	  },
   105	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
   106	  step(dt: number, inp: GliderInput): void {
   107	    if (active()) advance(dt, inp);
   108	  },
   109	  exit(): void {
   110	    const u = new URL(location.href);
   111	    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
   112	    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
   113	    else location.replace(u.toString());
   114	  },
   115	};
   116	
   117	export function setupExplore(ctrl: SwingController): void {
   118	  exNightBind(ctrl);
   119	  setupStroll(ctrl, () => explore.exit());
   120	  window.addEventListener('keydown', (e) => {
   121	    if (!inGlider() && !stroll.inMode()) return;
   122	    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn (bay dù, đi dạo và hai chế độ xem)
   123	    if (watching || stroll.inMode()) return;   // xem: không lái; đi dạo: phím do stroll/index.ts ghi
   124	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
   125	    const t = e.target as HTMLElement | null;
   126	    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
   127	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
   128	    const k = e.key.toLowerCase(); keys.add(k);
   129	    if (k.startsWith('arrow')) e.preventDefault();
   130	  });
   131	  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
   132	  for (const id of ['langSelect', 'qualitySel']) {
   133	    const sel = document.getElementById(id); if (!sel) continue;
   134	    let byMouse = false;
   135	    sel.addEventListener('pointerdown', () => { byMouse = true; });
   136	    sel.addEventListener('keydown', () => { byMouse = false; });
   137	    sel.addEventListener('change', () => { if (byMouse && (active() || stroll.active())) sel.blur(); byMouse = false; });
   138	  }
   139	  const q = new URLSearchParams(location.search);
   140	  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
   141	  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
   142	  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
   143	  if (q.get('explore') === 'glider') { explore.start(); return; }
   144	  if (q.get('explore') === 'stroll') { stroll.start(); return; }   // đi dạo một mình, không qua slot
   145	  if (!q.has('test') || q.has('chooser')) {
   146	    document.querySelector('button[data-pick="walk"]')?.addEventListener('click', () => stAvatars.preload(0));   // chọn thẻ Đi dạo: nạp nhân vật của mình ngay, trong lúc ở sảnh
   147	    exShowChooser((choice) => { if (choice === 'glider') explore.start(); else if (choice === 'walk') stroll.start(); },
   148	      (choice) => { if (choice === 'walk') stroll.startWatching(); else explore.startWatching(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
   149	  }
   150	}

