  1	/* ===== Phòng bầu trời chung: logic thuần, không phụ thuộc Cloudflare (Durable Object bọc ngoài) ===== */
  2	import { multiParams as P } from '../../../src/explore/multi/params';
  3	import { exSanitizeName } from '../../../src/explore/multi/protocol';
  4	import type { ServerMsg, Flyer, Kind } from '../../../src/explore/multi/protocol';
  5	import { exIsBad } from './badwords';
  6	
  7	export type Out = { to: string | 'all'; msg: ServerMsg };
  8	
  9	// pos: [slot, x, y, z, yaw, bank (người đi dạo: pose), giờ gửi]; giờ gửi = ts của khách (khách mới) hoặc giờ máy chủ nhận (khách cũ); dirty: có vị trí mới chưa phát
 10	interface Slot { id: string; name: string; seen: number; pos: number[] | null; dirty: boolean }
 11	interface Conn { stamps: number[] }
 12	
 13	const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
 14	const wrapPi = (a: number) => a - Math.round(a / (2 * Math.PI)) * 2 * Math.PI;   // góc về [−π, π]
 15	
 16	export class SkyRoom {
 17	  private conns = new Map<string, Conn>();
 18	  private slots: (Slot | null)[] = new Array(P.slots).fill(null);
 19	  private walkSlots: (Slot | null)[] = new Array(P.stroll.slots).fill(null);   // nhóm chỗ đi dạo, tách khỏi nhóm bay
 20	  private lastBroadcast = -Infinity;
 21	
 22	  private lobby(): Out {
 23	    const flyers: Flyer[] = [];
 24	    const walkers: Flyer[] = [];
 25	    this.slots.forEach((s, i) => { if (s) flyers.push({ slot: i, name: s.name }); });
 26	    this.walkSlots.forEach((s, i) => { if (s) walkers.push({ slot: i, name: s.name }); });
 27	    return { to: 'all', msg: { t: 'lobby', flyers, walkers } };
 28	  }
 29	
 30	  connect(id: string, now: number): Out[] | null {
 31	    if (!this.conns.has(id) && this.conns.size >= P.maxConns) return null;
 32	    this.conns.set(id, { stamps: [] });
 33	    return [{ to: id, msg: this.lobby().msg }];
 34	  }
 35	
 36	  slotOf(id: string): number { return this.slots.findIndex(s => s !== null && s.id === id); }   // slot bay, -1 nếu không bay
 37	
 38	  walkSlotOf(id: string): number { return this.walkSlots.findIndex(s => s !== null && s.id === id); }   // slot đi dạo, -1 nếu không đi dạo
 39	
 40	  kindOf(id: string): Kind | null { return this.slotOf(id) >= 0 ? 'fly' : this.walkSlotOf(id) >= 0 ? 'walk' : null; }
 41	
 42	  hasFlyers(): boolean { return this.slots.some(s => s !== null) || this.walkSlots.some(s => s !== null); }   // còn ai giữ slot (bay hoặc đi): giữ alarm quét
 43	
 44	  /* Giờ có tin cuối của người giữ slot (để lưu vào attachment); -1 nếu không giữ slot */
 45	  seenOf(id: string): number {
 46	    const i = this.slotOf(id);
 47	    if (i >= 0) return this.slots[i].seen;
 48	    const w = this.walkSlotOf(id);
 49	    return w < 0 ? -1 : this.walkSlots[w].seen;
 50	  }
 51	
 52	  /* Dựng lại sau hibernation. seen lấy từ attachment nếu có; không có (attachment cũ) thì coi như vừa im lặng gần hết hạn:
 53	     người còn bay có một chu kỳ nhịp sống để lên tiếng, người đã chết không được gia hạn thêm mỗi lần thức dậy */
 54	  restore(list: { id: string; slot: number; name: string; seen?: number; kind?: 'walk' }[], now: number): void {
 55	    for (const e of list) {
 56	      const group = e.kind === 'walk' ? this.walkSlots : this.slots;
 57	      if (e.slot < 0 || e.slot >= group.length) continue;
 58	      if (!this.conns.has(e.id)) this.conns.set(e.id, { stamps: [] });
 59	      const seen = typeof e.seen === 'number' && Number.isFinite(e.seen) ? Math.min(e.seen, now) : now - P.slotTimeoutMs + P.heartbeatMs;
 60	      group[e.slot] = { id: e.id, name: e.name, seen, pos: null, dirty: false };
 61	    }
 62	  }
 63	
 64	  message(id: string, raw: string, now: number): Out[] {
 65	    const conn = this.conns.get(id);
 66	    if (!conn || typeof raw !== 'string' || raw.length > P.maxMsgBytes) return [];
 67	    let m: any;
 68	    try { m = JSON.parse(raw); } catch { return []; }
 69	    if (!m || typeof m !== 'object') return [];
 70	    const kind = this.kindOf(id);
 71	    const group = kind === 'walk' ? this.walkSlots : this.slots;
 72	    const slot = kind === 'walk' ? this.walkSlotOf(id) : this.slotOf(id);
 73	    switch (m.t) {
 74	      case 'join': return this.onJoin(id, kind !== null, m.name, m.kind === 'walk', now);
 75	      case 'leave': return this.release(id) ? [this.lobby()] : [];
 76	      case 'hb': if (slot < 0) return []; group[slot].seen = now; return this.flush(now);
 77	      case 'pos': return slot >= 0 ? this.onPos(conn, group[slot]!, slot, kind === 'walk', m, now) : [];
 78	      default: return [];
 79	    }
 80	  }
 81	
 82	  private onJoin(id: string, holding: boolean, rawName: unknown, walk: boolean, now: number): Out[] {
 83	    if (holding) return [];
 84	    const name = typeof rawName === 'string' ? exSanitizeName(rawName) : null;
 85	    if (name === null || exIsBad(name)) return [{ to: id, msg: walk ? { t: 'rejected', why: 'name', kind: 'walk' } : { t: 'rejected', why: 'name' } }];
 86	    const group = walk ? this.walkSlots : this.slots;
 87	    const free = group.findIndex(s => s === null);
 88	    if (free < 0) return [{ to: id, msg: walk ? { t: 'rejected', why: 'full', kind: 'walk' } : { t: 'rejected', why: 'full' } }];
 89	    group[free] = { id, name, seen: now, pos: null, dirty: false };
 90	    return [{ to: id, msg: walk ? { t: 'joined', slot: free, kind: 'walk' } : { t: 'joined', slot: free } }, this.lobby()];
 91	  }
 92	
 93	  private onPos(conn: Conn, s: Slot, slot: number, walk: boolean, m: any, now: number): Out[] {
 94	    const { x, y, z, yaw, ts } = m;
 95	    const tilt = walk ? m.pose : m.bank;   // người đi dạo gửi pose, người bay gửi bank; trường kia bị bỏ qua
 96	    for (const v of [x, y, z, yaw, tilt]) if (typeof v !== 'number' || !Number.isFinite(v)) return [];
 97	    conn.stamps = conn.stamps.filter(t => now - t < 1000);
 98	    if (conn.stamps.length >= P.posMaxPerSec) return [];
 99	    conn.stamps.push(now);
100	    s.seen = now;
101	    const stamp = typeof ts === 'number' && Math.abs(ts) <= Number.MAX_SAFE_INTEGER ? ts : now;   // ts ngoài ±2^53 (kể cả NaN/∞) coi như không gửi, tránh đẩy độ lệch giờ của khách thành ∞
102	    if (walk) {
103	      const B = P.stroll.bounds;
104	      s.pos = [slot, clamp(x, B.x0, B.x1), clamp(y, P.stroll.yMin, P.stroll.yMax), clamp(z, B.z0, B.z1), wrapPi(yaw), clamp(Math.round(tilt), 0, P.stroll.poseMax), stamp];
105	    } else {
106	      s.pos = [slot, clamp(x, P.bounds.x0, P.bounds.x1), clamp(y, P.floor, P.ceiling), clamp(z, P.bounds.z0, P.bounds.z1), wrapPi(yaw), clamp(tilt, -P.bankMax, P.bankMax), stamp];
107	    }
108	    s.dirty = true;
109	    return this.flush(now);
110	  }
111	
112	  /* Phát gói gộp các slot có vị trí mới (cách lần trước >= broadcastMs). Vị trí bị hãm trong cửa sổ vẫn dirty nên đi ở lần phát sau (pos hoặc hb của bất kỳ ai).
113	     Không phát lại vị trí cũ: khách cũ đóng dấu theo giờ nhận nên mẫu lặp làm dù đứng rồi vọt. Khách mới đặt mẫu theo e[6] */
114	  private flush(now: number): Out[] {
115	    if (now - this.lastBroadcast < P.broadcastMs) return [];
116	    const f: number[][] = [], w: number[][] = [];
117	    for (const t of this.slots) if (t && t.dirty) { f.push(t.pos!); t.dirty = false; }
118	    for (const t of this.walkSlots) if (t && t.dirty) { w.push(t.pos!); t.dirty = false; }
119	    if (!f.length && !w.length) return [];
120	    this.lastBroadcast = now;
121	    return [{ to: 'all', msg: w.length ? { t: 'pos', f, w } : { t: 'pos', f } }];
122	  }
123	
124	  // Trả slot của kết nối; true nếu có slot được trả
125	  private release(id: string): boolean {
126	    const i = this.slotOf(id);
127	    if (i >= 0) { this.slots[i] = null; return true; }
128	    const w = this.walkSlotOf(id);
129	    if (w < 0) return false;
130	    this.walkSlots[w] = null;
131	    return true;
132	  }
133	
134	  disconnect(id: string): Out[] {
135	    this.conns.delete(id);
136	    return this.release(id) ? [this.lobby()] : [];
137	  }
138	
139	  sweep(now: number): Out[] {
140	    const out: Out[] = [];
141	    for (const group of [this.slots, this.walkSlots]) group.forEach((s, i) => {
142	      if (s && now - s.seen > P.slotTimeoutMs) { out.push({ to: s.id, msg: { t: 'released' } }); group[i] = null; }
143	    });
144	    if (out.length) out.push(this.lobby());
145	    return out;
146	  }
147	}
  1	/* ===== Worker + Durable Object phòng bầu trời chung: bọc SkyRoom, WebSocket hibernation ===== */
  2	import { multiParams as P } from '../../../src/explore/multi/params';
  3	import { SkyRoom } from './room';
  4	import type { Out } from './room';
  5	
  6	interface Env { SKY: DurableObjectNamespace; ALLOWED_ORIGINS: string }
  7	interface Att { id: string; slot: number; name: string; seen?: number; kind?: 'walk' }   // seen: giờ có tin cuối của người giữ slot, ghi thưa (mỗi heartbeatMs) để sống sót
  8	
  9	// So khớp scheme + hostname, bỏ cổng
 10	function originKey(o: string): string | null {
 11	  try { const u = new URL(o); return u.protocol + '//' + u.hostname; } catch { return null; }
 12	}
 13	
 14	// Mục cho phép có '*' (vd. bản xem trước PR của Netlify): '*' chỉ khớp một đoạn chữ thường/số, không có '.' hay '-'
 15	function originAllowed(key: string, pattern: string): boolean {
 16	  const p = originKey(pattern.replace(/\*/g, 'x'));
 17	  if (!p) return false;
 18	  if (!pattern.includes('*')) return p === key;
 19	  const re = new RegExp('^' + pattern.trim().split('*').map(s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('[a-z0-9]+') + '$');
 20	  return re.test(key);
 21	}
 22	
 23	export default {
 24	  async fetch(req: Request, env: Env): Promise<Response> {
 25	    const url = new URL(req.url);
 26	    if (url.pathname !== '/sky') return new Response('Not found', { status: 404 });
 27	    if (req.headers.get('Upgrade') !== 'websocket') return new Response('Expected WebSocket', { status: 426 });
 28	    const key = originKey(req.headers.get('Origin') || '');
 29	    if (!key || !env.ALLOWED_ORIGINS.split(',').some(s => originAllowed(key, s.trim()))) return new Response('Forbidden', { status: 403 });
 30	    return env.SKY.get(env.SKY.idFromName('sky')).fetch(req);
 31	  }
 32	};
 33	
 34	export class SkyObject implements DurableObject {
 35	  private room = new SkyRoom();
 36	  private names = new Map<number, string>();
 37	  private walkNames = new Map<number, string>();   // tên người đi dạo theo slot, lấy từ walkers của lobby
 38	  private armed: boolean | null = null;   // đã đặt alarm chưa; null = chưa biết (vừa dựng hoặc vừa thức dậy): hỏi storage một lần
 39	
 40	  constructor(private state: DurableObjectState, _env: Env) {
 41	    // Đánh thức sau hibernation: dựng lại phòng từ attachment của từng socket
 42	    const now = Date.now();
 43	    const list: Att[] = [];
 44	    for (const ws of this.state.getWebSockets()) {
 45	      const a = ws.deserializeAttachment() as Att | null;
 46	      if (!a) continue;
 47	      this.room.connect(a.id, now);
 48	      if (a.slot >= 0) list.push(a);
 49	    }
 50	    this.room.restore(list, now);
 51	  }
 52	
 53	  async fetch(_req: Request): Promise<Response> {
 54	    const pair = new WebSocketPair();
 55	    const [client, server] = [pair[0], pair[1]];
 56	    const id = crypto.randomUUID();
 57	    this.state.acceptWebSocket(server);
 58	    server.serializeAttachment({ id, slot: -1, name: '' } as Att);
 59	    const outs = this.room.connect(id, Date.now());
 60	    if (outs === null) { server.close(1013, 'full'); return new Response(null, { status: 503 }); }
 61	    this.dispatch(outs);
 62	    return new Response(null, { status: 101, webSocket: client });
 63	  }
 64	
 65	  async webSocketMessage(ws: WebSocket, data: string | ArrayBuffer): Promise<void> {
 66	    const a = ws.deserializeAttachment() as Att | null;
 67	    if (!a || typeof data !== 'string') return;
 68	    this.dispatch(this.room.message(a.id, data, Date.now()));
 69	    await this.armAlarm();
 70	  }
 71	
 72	  async webSocketClose(ws: WebSocket): Promise<void> { this.drop(ws); }
 73	  async webSocketError(ws: WebSocket): Promise<void> { this.drop(ws); }
 74	
 75	  async alarm(): Promise<void> {
 76	    this.armed = false;   // alarm đã chạy thì không còn alarm nào chờ
 77	    this.dispatch(this.room.sweep(Date.now()));
 78	    await this.armAlarm();
 79	  }
 80	
 81	  private drop(ws: WebSocket): void {
 82	    const a = ws.deserializeAttachment() as Att | null;
 83	    if (a) this.dispatch(this.room.disconnect(a.id));
 84	  }
 85	
 86	  // Gửi tin ra socket rồi ghi lại slot/tên/seen mới vào attachment (để sống sót qua hibernation); seen chỉ ghi khi cũ hơn heartbeatMs
 87	  private dispatch(outs: Out[]): void {
 88	    const socks = this.state.getWebSockets();
 89	    for (const o of outs) {
 90	      const text = JSON.stringify(o.msg);
 91	      for (const ws of socks) {
 92	        const a = ws.deserializeAttachment() as Att | null;
 93	        if (!a || (o.to !== 'all' && o.to !== a.id)) continue;
 94	        try { ws.send(text); } catch { /* socket đã đóng */ }
 95	      }
 96	      if (o.msg.t === 'lobby') {
 97	        this.names = new Map(o.msg.flyers.map(f => [f.slot, f.name]));
 98	        this.walkNames = new Map((o.msg.walkers ?? []).map(f => [f.slot, f.name]));
 99	      }
100	    }
101	    for (const ws of socks) {
102	      const a = ws.deserializeAttachment() as Att | null;
103	      if (!a) continue;
104	      const kind = this.room.kindOf(a.id);
105	      const walk = kind === 'walk';
106	      const slot = walk ? this.room.walkSlotOf(a.id) : this.room.slotOf(a.id);
107	      const name = slot >= 0 ? ((walk ? this.walkNames : this.names).get(slot) ?? a.name) : '';
108	      const seen = this.room.seenOf(a.id);
109	      const stale = slot >= 0 && !(seen - (a.seen ?? -Infinity) < P.heartbeatMs);
110	      if (slot !== a.slot || name !== a.name || (a.kind === 'walk') !== walk || stale) {
111	        const next: Att = slot < 0 ? { id: a.id, slot, name } : walk ? { id: a.id, slot, name, seen, kind: 'walk' } : { id: a.id, slot, name, seen };
112	        ws.serializeAttachment(next);
113	      }
114	    }
115	  }
116	
117	  private async armAlarm(): Promise<void> {
118	    if (!this.room.hasFlyers() || this.armed) return;
119	    if (this.armed === null && (await this.state.storage.getAlarm()) !== null) { this.armed = true; return; }
120	    this.armed = true;
121	    try { await this.state.storage.setAlarm(Date.now() + P.sweepMs); } catch (e) { this.armed = false; throw e; }
122	  }
123	}
