 11	export class MultiSession {
 12	  phase: Phase = 'connecting';
 13	  flyers: Flyer[] = [];
 14	  walkers: Flyer[] = [];   // người đi dạo (lobby.walkers); máy chủ cũ không gửi
 15	  mySlot = -1;
 16	  watched = -1;       // slot đang xem (trong nhóm cùng loại), -1 = không ai
 17	  invite = false;     // đang xem và còn chỗ trống
 18	  notice: Notice = '';
 19	  name = '';
