 60	  }
 61	
 62	  // Người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh) thay cho bank
 63	  sendWalk(x: number, y: number, z: number, yaw: number, pose: number, ts: number): void {
 64	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, pose, ts });
 65	  }
 66	
 67	  heartbeat(): void {
 68	    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
