113	      case 'lobby':
114	        if (this.first && this.kind === 'walk' && !Array.isArray(m.walkers)) { this.first = false; this.offline(); return; }
115	        this.flyers = m.flyers;
116	        this.walkers = Array.isArray(m.walkers) ? m.walkers : [];
