361	export const exRemotes = {
362	  /* Danh sách người bay đổi (sảnh, vào, ra): dựng dù cho slot mới, đặt lại slot đổi chủ, ẩn slot trống */
363	  sync(flyers: Flyer[], mySlot: number): void {
364	    me = mySlot;
365	    for (let i = 0; i < slots.length; i++) {
366	      const s = slots[i];
367	      let name: string | null = null;
368	      if (i !== mySlot) for (const f of flyers) if (f.slot === i) { name = f.name; break; }
369	      if (name === null) { s.name = null; hide(s); continue; }
370	      if (name !== s.name) {
371	        s.name = name; hide(s);
372	        if (!s.group) { s.group = exBuildGlider(M.colors[i % M.colors.length]); s.group.visible = false; s.group.traverse(o => o.layers.set(1)); scene.add(s.group); }   // lớp 1: không vẽ vào phản chiếu nước, g
373	      }
