414	/* ===== Dù lượn nhiều người: nội suy vị trí dù người khác (thuần, không import) =====
415	   Vòng đệm cố định 8 mẫu (t, x, y, z, yaw, bank), nội suy tuyến tính, yaw đi đường ngắn qua ±π, kẹp ở mẫu cuối. Không cấp phát khi push/sample (D-018).
416	   Mẫu đặt theo giờ của người gửi (e[6]) quy ra giờ khách, nên trễ mạng và việc máy chủ gộp gói không làm dù đứng rồi vọt. */
417	const N = 8, W = 6;   // số mẫu tối đa; số trường mỗi mẫu
418	export interface ExPose { x: number; y: number; z: number; yaw: number; bank: number }
419	export interface ExClockParams { clockRelax: number; clockSlewMs: number; clockWarmup: number }   // xem multiParams
420	
421	export class ExTrack {
422	  private buf = new Float64Array(N * W);
423	  private head = 0;      // chỉ số ô sẽ ghi tiếp
424	  private n = 0;         // số mẫu đang có
425	  private off = NaN;     // độ lệch giờ người gửi → giờ khách (ms); NaN = chưa có mẫu nào có giờ
426	  private fed = 0;       // số mẫu có giờ đã nhận: clockWarmup mẫu đầu lấy thẳng mức nhỏ nhất (gói đầu có thể trễ vì khung hình chậm), sau đó mới giới hạn slew
427	  get count(): number { return this.n; }
428	
429	  push(t: number, x: number, y: number, z: number, yaw: number, bank: number): void {
430	    if (this.n > 0 && t <= this.buf[((this.head + N - 1) % N) * W]) return;   // mẫu cũ hoặc trùng giờ: bỏ để giữ thứ tự
431	    const o = this.head * W, b = this.buf;
432	    b[o] = t; b[o + 1] = x; b[o + 2] = y; b[o + 3] = z; b[o + 4] = yaw; b[o + 5] = bank;
433	    this.head = (this.head + 1) % N;
434	    if (this.n < N) this.n++;
435	  }
436	
437	  /* Một mục của gói pos e = [slot, x, y, z, yaw, bank, giờ gửi?] nhận lúc nowMs.
438	     Có giờ gửi (máy chủ mới): giờ khách = giờ gửi + độ lệch; độ lệch bám mức nhỏ nhất (gói ít trễ nhất) nhưng sau clockWarmup mẫu đầu mỗi mẫu chỉ giảm tối đa clockSl
439	     và nới lên clockRelax phần chênh khi mạng chậm đi: độ lệch đổi chậm nên dù không bị co giãn thời gian.
440	     Không có (máy chủ cũ phát lại vị trí cũ của mọi slot mỗi gói): đóng dấu giờ nhận, bỏ mục trùng mẫu cuối để dù không đứng chờ */
441	  feed(e: number[], nowMs: number, k: ExClockParams): void {
442	    const ts = e[6];
443	    if (typeof ts === 'number' && Number.isFinite(ts)) {
444	      const c = nowMs - ts;
445	      if (this.off !== this.off || (c < this.off && this.fed < k.clockWarmup)) this.off = c;
446	      else if (c < this.off) this.off -= Math.min(this.off - c, k.clockSlewMs);
447	      else this.off += (c - this.off) * k.clockRelax;
448	      this.fed++;
449	      this.push(ts + this.off, e[1], e[2], e[3], e[4], e[5]);
450	      return;
451	    }
452	    if (this.n > 0) {
453	      const o = ((this.head + N - 1) % N) * W, b = this.buf;
454	      if (b[o + 1] === e[1] && b[o + 2] === e[2] && b[o + 3] === e[3] && b[o + 4] === e[4] && b[o + 5] === e[5]) return;
455	    }
456	    this.push(nowMs, e[1], e[2], e[3], e[4], e[5]);
457	  }
458	
459	  /* Ghi vị trí tại thời điểm t vào out; false nếu chưa có mẫu.
460	     step = true: trường thứ 6 (bank; người đi dạo dùng chở pose) không nội suy, lấy nguyên của mẫu trước, tới đúng giờ mẫu sau mới đổi */
461	  sample(t: number, out: ExPose, step = false): boolean {
