475	    out.y = b[a + 2] + (b[c + 2] - b[a + 2]) * k;
476	    out.z = b[a + 3] + (b[c + 3] - b[a + 3]) * k;
477	    let dy = b[c + 4] - b[a + 4];
478	    dy -= Math.round(dy / (2 * Math.PI)) * 2 * Math.PI;
479	    out.yaw = b[a + 4] + dy * k;
480	    out.bank = step ? b[(k >= 1 ? c : a) + 5] : b[a + 5] + (b[c + 5] - b[a + 5]) * k;
481	    return true;
482	  }
