 24	const slots: RemoteSlot[] = Array.from({ length: M.slots }, () => ({
 25	  name: null, group: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
 26	  state: { pos: new THREE.Vector3(), yaw: 0, bank: 0, ret: 0, speed: 0 }, live: false
 27	}));
 28	let me = -1;
