 44	      if (name !== s.name) {
 45	        s.name = name; hide(s);
 46	        if (!s.group) { s.group = exBuildGlider(M.colors[i % M.colors.length]); s.group.visible = false; s.group.traverse(o => o.layers.set(1)); scene.add(s.group); }   // lớp 1: không vẽ 
 47	      }
 48	    }
 49	  },
 50	
 51	  /* Gói vị trí gộp: f = [slot, x, y, z, yaw, bank, giờ gửi?]; chỉ nhận slot đã biết chủ và không phải của mình */
 52	  onPos(f: number[][], nowMs: number): void {
 53	    for (const e of f) {
 54	      const i = e[0], s = slots[i];
 55	      if (!s || i === me || s.name === null) continue;
 56	      s.track.feed(e, nowMs, M);
 57	    }
 58	  },
 59	
 60	  update(nowMs: number): void {
