 87	};
 88	/* ===== Dù lượn nhiều người: nội suy vị trí dù người khác (thuần, không import) =====
 89	   Vòng đệm cố định 8 mẫu (t, x, y, z, yaw, bank), nội suy tuyến tính, yaw đi đường ngắn qua ±π, kẹp ở mẫu cuối. Không cấp phát khi push/sample (D-018).
 90	   Mẫu đặt theo giờ của người gửi (e[6]) quy ra giờ khách, nên trễ mạng và việc máy chủ gộp gói không làm dù đứng rồi vọt. */
 91	const N = 8, W = 6;   // số mẫu tối đa; số trường mỗi mẫu
 92	export interface ExPose { x: number; y: number; z: number; yaw: number; bank: number }
 93	export interface ExClockParams { clockRelax: number; clockSlewMs: number; clockWarmup: number }   // xem multiParams
 94	
 95	export class ExTrack {
 96	  private buf = new Float64Array(N * W);
 97	  private head = 0;      // chỉ số ô sẽ ghi tiếp
 98	  private n = 0;         // số mẫu đang có
 99	  private off = NaN;     // độ lệch giờ người gửi → giờ khách (ms); NaN = chưa có mẫu nào có giờ
100	  private fed = 0;       // số mẫu có giờ đã nhận: clockWarmup mẫu đầu lấy thẳng mức nhỏ nhất (gói đầu có thể trễ vì khung hình chậm), sau đó mới gi�
101	  get count(): number { return this.n; }
102	
103	  push(t: number, x: number, y: number, z: number, yaw: number, bank: number): void {
104	    if (this.n > 0 && t <= this.buf[((this.head + N - 1) % N) * W]) return;   // mẫu cũ hoặc trùng giờ: bỏ để giữ thứ tự
105	    const o = this.head * W, b = this.buf;
106	    b[o] = t; b[o + 1] = x; b[o + 2] = y; b[o + 3] = z; b[o + 4] = yaw; b[o + 5] = bank;
107	    this.head = (this.head + 1) % N;
108	    if (this.n < N) this.n++;
109	  }
110	
111	  /* Một mục của gói pos e = [slot, x, y, z, yaw, bank, giờ gửi?] nhận lúc nowMs.
112	     Có giờ gửi (máy chủ mới): giờ khách = giờ gửi + độ lệch; độ lệch bám mức nhỏ nhất (gói ít trễ nhất) nhưng sau clockWarmup mẫu đầu mỗi mẫu 
113	     và nới lên clockRelax phần chênh khi mạng chậm đi: độ lệch đổi chậm nên dù không bị co giãn thời gian.
114	     Không có (máy chủ cũ phát lại vị trí cũ của mọi slot mỗi gói): đóng dấu giờ nhận, bỏ mục trùng mẫu cuối để dù không đứng chờ */
115	  feed(e: number[], nowMs: number, k: ExClockParams): void {
116	    const ts = e[6];
117	    if (typeof ts === 'number' && Number.isFinite(ts)) {
118	      const c = nowMs - ts;
119	      if (this.off !== this.off || (c < this.off && this.fed < k.clockWarmup)) this.off = c;
120	      else if (c < this.off) this.off -= Math.min(this.off - c, k.clockSlewMs);
121	      else this.off += (c - this.off) * k.clockRelax;
122	      this.fed++;
123	      this.push(ts + this.off, e[1], e[2], e[3], e[4], e[5]);
124	      return;
125	    }
126	    if (this.n > 0) {
127	      const o = ((this.head + N - 1) % N) * W, b = this.buf;
128	      if (b[o + 1] === e[1] && b[o + 2] === e[2] && b[o + 3] === e[3] && b[o + 4] === e[4] && b[o + 5] === e[5]) return;
129	    }
130	    this.push(nowMs, e[1], e[2], e[3], e[4], e[5]);
131	  }
132	
133	  /* Ghi vị trí tại thời điểm t vào out; false nếu chưa có mẫu.
134	     step = true: trường thứ 6 (bank; người đi dạo dùng chở pose) không nội suy, lấy nguyên của mẫu trước, tới đúng giờ mẫu sau mới đổi */
135	  sample(t: number, out: ExPose, step = false): boolean {
136	    if (this.n === 0) return false;
137	    const b = this.buf, first = (this.head + N - this.n) % N * W;
138	    const last = ((this.head + N - 1) % N) * W;
139	    let a = first, c = first;
140	    if (t >= b[last]) a = c = last;
141	    else if (t > b[first]) {
142	      for (let i = 0; i < this.n - 1; i++) {
143	        const p = (first + i * W) % (N * W), q = (p + W) % (N * W);
144	        if (t <= b[q]) { a = p; c = q; break; }
145	      }
146	    }
147	    const k = a === c ? 0 : (t - b[a]) / (b[c] - b[a]);
148	    out.x = b[a + 1] + (b[c + 1] - b[a + 1]) * k;
149	    out.y = b[a + 2] + (b[c + 2] - b[a + 2]) * k;
150	    out.z = b[a + 3] + (b[c + 3] - b[a + 3]) * k;
151	    let dy = b[c + 4] - b[a + 4];
152	    dy -= Math.round(dy / (2 * Math.PI)) * 2 * Math.PI;
153	    out.yaw = b[a + 4] + dy * k;
154	    out.bank = step ? b[(k >= 1 ? c : a) + 5] : b[a + 5] + (b[c + 5] - b[a + 5]) * k;
155	    return true;
156	  }
157	
158	  reset(): void { this.n = 0; this.head = 0; this.off = NaN; this.fed = 0; }
159	}
160	/* ===== Dù lượn và đi dạo nhiều người: nhãn tên nổi cạnh người chơi khác =====
161	   Một div cho mỗi slot bay và mỗi slot đi dạo trong #exMpLabels. Dù: điểm đặt nhãn thấp hơn dù labelBelow m (tên nằm dưới cánh, không che dù);
162	   người đi dạo: cao hơn chân CONFIG.stroll.labelAbove m (trên đầu). Ẩn khi sau camera hoặc slot chưa hiện; nhân vật của mình không có nhãn.
163	   Chỉ ghi DOM khi chữ đổi (tên + khoảng cách, làm tươi ≤ 5 lần/s) hoặc vị trí lệch quá 1 px. Không cấp phát mỗi khung (D-018). */
164	import * as THREE from 'three';
165	import { CONFIG } from '../../config';
166	import type { exRemotes } from './remote';
167	import type { stAvatars } from '../stroll/avatars';
168	
169	const M = CONFIG.explore.multi, NW = M.stroll.slots;
170	interface Lab { el: HTMLElement; txt: string; x: number; y: number; shown: boolean; tMs: number }
171	let labs: Lab[] | null = null;   // M.slots nhãn dù rồi NW nhãn người đi dạo
172	const _v = new THREE.Vector3();
173	
174	function init(): Lab[] | null {
175	  const box = document.getElementById('exMpLabels');
176	  if (!box) return null;
177	  return Array.from({ length: M.slots + NW }, () => {
178	    const el = document.createElement('div'); el.className = 'ex-mp-label'; el.hidden = true; box.appendChild(el);
179	    return { el, txt: '', x: -1e9, y: -1e9, shown: false, tMs: -1e9 };
180	  });
181	}
182	
183	// Khoảng cách làm tròn: < 1000 m ghi "NNN m", còn lại "N.N km"
184	const dist = (d: number) => d < 1000 ? `${Math.round(d)} m` : `${(d / 1000).toFixed(1)} km`;
185	
186	/* Đặt một nhãn tại điểm (x, y, z) với tên name; trả true nếu hiện */
187	function place(L: Lab, camera: THREE.Camera, x: number, y: number, z: number, name: string, nowMs: number, w: number, h: number): boolean {
188	  _v.set(x, y, z).applyMatrix4(camera.matrixWorldInverse);
189	  if (-_v.z <= 0.1) return false;   // sau camera
190	  _v.applyMatrix4(camera.projectionMatrix);
191	  const px = (_v.x * 0.5 + 0.5) * w, py = (-_v.y * 0.5 + 0.5) * h;
192	  if (px <= -80 || px >= w + 80 || py <= -40 || py >= h + 40) return false;
193	  if (nowMs - L.tMs >= 200) {
194	    L.tMs = nowMs;
195	    const txt = `${name} · ${dist(Math.hypot(x - camera.position.x, y - camera.position.y, z - camera.position.z))}`;
196	    if (txt !== L.txt) { L.txt = txt; L.el.textContent = txt; }
197	  }
198	  if (Math.abs(px - L.x) > 1 || Math.abs(py - L.y) > 1) { L.x = px; L.y = py; L.el.style.transform = `translate(${px.toFixed(0)}px,${py.toFixed(0)}px) translateX(-50%)`; }
199	  return true;
200	}
201	
202	export function exLabelsUpdate(camera: THREE.Camera, remotes: typeof exRemotes, nowMs: number, walkers?: typeof stAvatars): void {
203	  if (!labs && !(labs = init())) return;
204	  const w = window.innerWidth, h = window.innerHeight;
205	  for (let i = 0; i < M.slots; i++) {
206	    const L = labs[i], st = remotes.slotState(i);
207	    const vis = !!st && place(L, camera, st.pos.x, st.pos.y - M.labelBelow, st.pos.z, remotes.name(i), nowMs, w, h);
208	    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
209	  }
210	  for (let i = 0; i < NW; i++) {
211	    const L = labs[M.slots + i], st = walkers && i !== walkers.self ? walkers.slotState(i) : null, nm = st ? walkers!.name(i) : null;
212	    const vis = !!st && nm !== null && place(L, camera, st.x, st.y + CONFIG.stroll.labelAbove, st.z, nm, nowMs, w, h);
213	    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
214	  }
215	}
216	
217	/* Ẩn hết nhãn (rời phòng) */
218	export function exLabelsClear(): void {
219	  if (!labs) return;
220	  for (const L of labs) { L.shown = false; L.el.hidden = true; L.x = L.y = -1e9; }
221	}

